from pathlib import Path

path = Path('app/lib/features/drop/presentation/create_drop_screen.dart')
text = path.read_text()

# 1) Recompose the main editor body so avatar/audience form one compact
# identity row and the text editor spans the full width below it, matching
# the approved mobile mockup while keeping all existing posting logic.
build_start = text.index('  @override\n  Widget build(BuildContext context) {')
body_start = text.index('              Expanded(\n                child: SingleChildScrollView(', build_start)
body_end = text.index('              _buildToolbar(),', body_start)
new_body = '''              Expanded(\n                child: SingleChildScrollView(\n                  keyboardDismissBehavior:\n                      ScrollViewKeyboardDismissBehavior.onDrag,\n                  padding: const EdgeInsets.fromLTRB(\n                    WynSpacing.space4,\n                    WynSpacing.space4,\n                    WynSpacing.space4,\n                    WynSpacing.space4,\n                  ),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Row(\n                        children: [\n                          AvatarCircle(\n                            imageUrl: _ownProfile?.avatarUrl,\n                            fallbackText: _ownProfile?.username ?? '',\n                            radius: 22,\n                            ring: true,\n                          ),\n                          const SizedBox(width: WynSpacing.space3),\n                          _AudienceChip(\n                            value: _audience,\n                            onTap:\n                                _isSharing ? null : _showAudiencePicker,\n                          ),\n                        ],\n                      ),\n                      const SizedBox(height: WynSpacing.space4),\n                      MentionInput(\n                        controller: _captionController,\n                        profileRepository: _profileRepository,\n                        hashtagRepository: widget._hashtagRepository,\n                        onMentionedUsersChanged: (ids) =>\n                            setState(() => _mentionedUserIds = ids),\n                        maxLength: _captionMaxLength,\n                        maxLines: null,\n                        minLines: 6,\n                        enabled: !_isSharing,\n                        style: const TextStyle(\n                          fontSize: 22,\n                          color: WynColors.ink,\n                          height: 1.4,\n                        ),\n                        decoration: InputDecoration(\n                          hintText: _mode == _ComposeMode.poll\n                              ? 'ตั้งคำถามโพล...'\n                              : 'มีอะไรเกิดขึ้นบ้าง',\n                          hintStyle: const TextStyle(\n                            fontSize: 22,\n                            color: WynColors.faint,\n                            height: 1.4,\n                          ),\n                          border: InputBorder.none,\n                          counterText: '',\n                          contentPadding: EdgeInsets.zero,\n                          isDense: true,\n                        ),\n                      ),\n                      if (_mode == _ComposeMode.image)\n                        _buildImageStrip()\n                      else\n                        _buildPollComposer(),\n                      if (_selectedLocation != null) ...[\n                        const SizedBox(height: WynSpacing.space3),\n                        _LocationChip(\n                          location: _selectedLocation!,\n                          onRemove:\n                              _isSharing ? null : _removeLocation,\n                        ),\n                      ],\n                      if (_captionController.text.length >\n                          _captionMaxLength * 0.8)\n                        Padding(\n                          padding: const EdgeInsets.only(\n                            top: WynSpacing.space1,\n                          ),\n                          child: Align(\n                            alignment: Alignment.centerRight,\n                            child: Text(\n                              '${_captionMaxLength - _captionController.text.length}',\n                              style: const TextStyle(\n                                fontSize: 13,\n                                color: WynColors.sapphire,\n                              ),\n                            ),\n                          ),\n                        ),\n                      if (_errorMessage != null) ...[\n                        const SizedBox(height: WynSpacing.space2),\n                        Text(\n                          _errorMessage!,\n                          style: TextStyle(\n                            color: Theme.of(context).colorScheme.error,\n                          ),\n                        ),\n                      ],\n                    ],\n                  ),\n                ),\n              ),\n'''
text = text[:body_start] + new_body + text[body_end:]

# 2) Header: exact visual hierarchy from the approved mockup -- Cancel,
# centered Draft, compact Post pill. Keep the same keys/types so existing
# behaviour and regression tests remain valid.
header_start = text.index('  Widget _buildHeader() {')
header_end = text.index("  // 04-drop.tsx's ImageStrip", header_start)
new_header = '''  Widget _buildHeader() {\n    final draftControl = _draftId == null && !_isRestricted\n        ? TextButton.icon(\n            key: const Key('open_drafts_button'),\n            onPressed:\n                _isSharing || _isSavingDraft ? null : _openDrafts,\n            style: TextButton.styleFrom(\n              foregroundColor: WynColors.ink,\n              padding: const EdgeInsets.symmetric(\n                horizontal: WynSpacing.space2,\n              ),\n              minimumSize:\n                  const Size(0, WynSpacing.touchTargetMin),\n              tapTargetSize: MaterialTapTargetSize.shrinkWrap,\n            ),\n            icon: const Icon(\n              Icons.edit_outlined,\n              size: 19,\n              color: WynColors.ink,\n            ),\n            label: const Text(\n              'ร่าง',\n              style: TextStyle(\n                fontSize: 16,\n                fontWeight: FontWeight.w600,\n                color: WynColors.ink,\n              ),\n            ),\n          )\n        : const Row(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Icon(Icons.edit_outlined, size: 19, color: WynColors.ink),\n              SizedBox(width: 6),\n              Text(\n                'ร่าง',\n                style: TextStyle(\n                  fontSize: 16,\n                  fontWeight: FontWeight.w600,\n                  color: WynColors.ink,\n                ),\n              ),\n            ],\n          );\n\n    return SizedBox(\n      height: 70,\n      child: Stack(\n        alignment: Alignment.center,\n        children: [\n          Align(\n            alignment: Alignment.centerLeft,\n            child: Padding(\n              padding: const EdgeInsets.only(left: WynSpacing.space4),\n              child: TextButton(\n                key: const Key('cancel_button'),\n                onPressed: _handleClose,\n                style: TextButton.styleFrom(\n                  foregroundColor: WynColors.ink,\n                  padding: EdgeInsets.zero,\n                  minimumSize: const Size(54, WynSpacing.touchTargetMin),\n                  alignment: Alignment.centerLeft,\n                ),\n                child: const Text(\n                  'ยกเลิก',\n                  style: TextStyle(\n                    fontSize: 15.5,\n                    fontWeight: FontWeight.w600,\n                    color: WynColors.ink,\n                  ),\n                ),\n              ),\n            ),\n          ),\n          Center(child: draftControl),\n          Align(\n            alignment: Alignment.centerRight,\n            child: Padding(\n              padding: const EdgeInsets.only(right: WynSpacing.space4),\n              child: Semantics(\n                label: _isRestricted\n                    ? 'โพสต์ ปิดใช้งานเนื่องจากบัญชีถูกจำกัดการโพสต์ชั่วคราว'\n                    : null,\n                excludeSemantics: _isRestricted,\n                child: TextButton(\n                  key: const Key('post_button'),\n                  onPressed: _canShare ? _share : null,\n                  style: TextButton.styleFrom(\n                    backgroundColor:\n                        _canShare ? WynColors.ink : WynColors.hairline,\n                    foregroundColor: _canShare\n                        ? WynColors.paper\n                        : WynColors.mutedNeutral,\n                    minimumSize: const Size(72, 42),\n                    padding: const EdgeInsets.symmetric(horizontal: 18),\n                    shape: const StadiumBorder(),\n                  ),\n                  child: _isSharing\n                      ? SizedBox(\n                          height: 16,\n                          width: 16,\n                          child: CircularProgressIndicator(\n                            strokeWidth: 2,\n                            color: _canShare\n                                ? WynColors.paper\n                                : WynColors.mutedNeutral,\n                          ),\n                        )\n                      : const Text(\n                          'โพสต์',\n                          style: TextStyle(\n                            fontSize: 15,\n                            fontWeight: FontWeight.w700,\n                          ),\n                        ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n'''
text = text[:header_start] + new_header + text[header_end:]

# 3) Bottom action area becomes the approved rounded attachment panel with
# labels while keeping each original toolbar key and handler.
toolbar_start = text.index('  Widget _buildToolbar() {')
toolbar_end = text.index('\n}\n\n/// WYN-097', toolbar_start)
new_toolbar = '''  Widget _buildToolbar() {\n    final imageDisabled =\n        _isSharing || _isCropping || _mode == _ComposeMode.poll;\n    return Container(\n      padding: const EdgeInsets.fromLTRB(\n        WynSpacing.space4,\n        WynSpacing.space3,\n        WynSpacing.space4,\n        WynSpacing.space3,\n      ),\n      decoration: BoxDecoration(\n        color: WynColors.paper,\n        border: const Border(\n          top: BorderSide(color: WynColors.hairline),\n        ),\n        borderRadius: const BorderRadius.only(\n          topLeft: Radius.circular(24),\n          topRight: Radius.circular(24),\n        ),\n        boxShadow: [\n          BoxShadow(\n            color: WynColors.ink.withValues(alpha: 0.04),\n            blurRadius: 18,\n            offset: const Offset(0, -4),\n          ),\n        ],\n      ),\n      child: Column(\n        mainAxisSize: MainAxisSize.min,\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          const Text(\n            'เพิ่มไปยังโพสต์ของคุณ',\n            style: TextStyle(\n              fontSize: 14.5,\n              fontWeight: FontWeight.w600,\n              color: WynColors.ink,\n            ),\n          ),\n          const SizedBox(height: WynSpacing.space3),\n          Row(\n            children: [\n              Expanded(\n                child: _ToolbarIcon(\n                  key: const Key('toolbar_photo_button'),\n                  icon: Icons.image_outlined,\n                  label: 'รูปภาพ',\n                  enabled: !imageDisabled,\n                  onTap: _pickMultipleImages,\n                  semanticsLabel: 'แนบรูปจากคลังภาพ',\n                ),\n              ),\n              const SizedBox(width: WynSpacing.space2),\n              Expanded(\n                child: _ToolbarIcon(\n                  key: const Key('toolbar_camera_button'),\n                  icon: Icons.camera_alt_outlined,\n                  label: 'กล้อง',\n                  enabled: !imageDisabled,\n                  onTap: () => _pickImage(ImageSource.camera),\n                  semanticsLabel: 'ถ่ายรูปใหม่',\n                ),\n              ),\n              const SizedBox(width: WynSpacing.space2),\n              Expanded(\n                child: _ToolbarIcon(\n                  key: const Key('toolbar_poll_button'),\n                  icon: Icons.bar_chart,\n                  label: 'โพล',\n                  enabled: !_isSharing,\n                  active: _mode == _ComposeMode.poll,\n                  onTap: () => setState(\n                    () => _mode = _mode == _ComposeMode.poll\n                        ? _ComposeMode.image\n                        : _ComposeMode.poll,\n                  ),\n                  semanticsLabel:\n                      _mode == _ComposeMode.poll ? 'ยกเลิกโพล' : 'สร้างโพล',\n                ),\n              ),\n              const SizedBox(width: WynSpacing.space2),\n              Expanded(\n                child: _ToolbarIcon(\n                  key: const Key('toolbar_location_button'),\n                  icon: Icons.location_on_outlined,\n                  label: 'สถานที่',\n                  enabled: !_isSharing,\n                  active: _selectedLocation != null,\n                  onTap: _showLocationPicker,\n                  semanticsLabel: 'เพิ่มตำแหน่งที่ตั้ง',\n                ),\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n'''
text = text[:toolbar_start] + new_toolbar + text[toolbar_end:]

# 4) Audience chip gets a leading audience icon like the approved mockup.
needle = '''          child: Row(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Text(audienceOptionLabel(value),'''
replacement = '''          child: Row(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Icon(\n                _audienceOptionIcon(value),\n                size: 14,\n                color: WynColors.ink,\n              ),\n              const SizedBox(width: 5),\n              Text(audienceOptionLabel(value),'''
if needle not in text:
    raise RuntimeError('Audience chip anchor not found')
text = text.replace(needle, replacement, 1)

# 5) Restyle the toolbar component into labelled rounded tiles. Tests still
# find the descendant InkWell and can verify disabled state exactly as before.
component_start = text.index('class _ToolbarIcon extends StatelessWidget {')
component_end = text.index('\n/// One ratio choice', component_start)
new_component = '''class _ToolbarIcon extends StatelessWidget {\n  const _ToolbarIcon({\n    super.key,\n    required this.icon,\n    required this.label,\n    required this.enabled,\n    required this.onTap,\n    required this.semanticsLabel,\n    this.active = false,\n  });\n\n  final IconData icon;\n  final String label;\n  final bool enabled;\n  final VoidCallback onTap;\n  final String semanticsLabel;\n  final bool active;\n\n  @override\n  Widget build(BuildContext context) {\n    final foreground = !enabled\n        ? WynColors.faint\n        : active\n            ? WynColors.sapphire\n            : WynColors.ink;\n    final background = active\n        ? WynColors.sapphireRing\n        : WynColors.surfaceTint;\n\n    return Semantics(\n      label: semanticsLabel,\n      button: true,\n      enabled: enabled,\n      excludeSemantics: true,\n      child: Material(\n        color: Colors.transparent,\n        child: InkWell(\n          onTap: enabled ? onTap : null,\n          borderRadius: BorderRadius.circular(18),\n          child: Ink(\n            height: 82,\n            decoration: BoxDecoration(\n              color: background,\n              borderRadius: BorderRadius.circular(18),\n              border: Border.all(\n                color: active ? WynColors.sapphireRing : WynColors.hairline,\n              ),\n            ),\n            child: Column(\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: [\n                Icon(icon, size: 24, color: foreground),\n                const SizedBox(height: 7),\n                Text(\n                  label,\n                  maxLines: 1,\n                  overflow: TextOverflow.ellipsis,\n                  style: TextStyle(\n                    fontSize: 12.5,\n                    fontWeight: FontWeight.w500,\n                    color: foreground,\n                  ),\n                ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n'''
text = text[:component_start] + new_component + text[component_end:]

path.write_text(text)
